package stowage

import (
	"strings"
	"sync"
)

// compartment 是舱位的内部记录。
type compartment struct {
	id        string
	maxWeight int64
	cargo     map[string]*cargo
}

// cargo 是货物的内部记录。
type cargo struct {
	id            string
	weight        int64
	destination   string
	allowMixed    bool
	compartmentID string // 空字符串表示未装载
}

// Registry 是舱单与配载的本地登记处。
//
// Registry 的所有方法都可以安全地并发调用。
type Registry struct {
	mu           sync.Mutex
	compartments map[string]*compartment
	cargos       map[string]*cargo
	adjustments  map[string]*AdjustmentResult // 已成功调整的编号 -> 保存的结果快照
	contents     map[string]string            // 已成功调整的编号 -> 规范化内容键
}

// NewRegistry 创建一个空的登记处。
func NewRegistry() *Registry {
	return &Registry{
		compartments: make(map[string]*compartment),
		cargos:       make(map[string]*cargo),
		adjustments:  make(map[string]*AdjustmentResult),
		contents:     make(map[string]string),
	}
}

// RegisterCompartment 登记一个舱位。
// 编号去掉首尾空白后不得为空，maxWeight 必须为正整数（千克）。
// 编号按去空白后的值识别并区分大小写；重复登记保留原记录。
func (r *Registry) RegisterCompartment(id string, maxWeight int64) error {
	r.mu.Lock()
	defer r.mu.Unlock()

	cid := strings.TrimSpace(id)
	if cid == "" {
		return fail(ErrInvalidID, "", "舱位编号为空")
	}
	if maxWeight <= 0 {
		return fail(ErrInvalidWeight, cid, "舱位 %s 最大承重必须为正整数千克，当前为 %d", cid, maxWeight)
	}
	if _, exists := r.compartments[cid]; exists {
		return fail(ErrAlreadyExists, cid, "舱位 %s 已存在", cid)
	}
	r.compartments[cid] = &compartment{
		id:        cid,
		maxWeight: maxWeight,
		cargo:     make(map[string]*cargo),
	}
	return nil
}

// RegisterCargo 登记一件货物。
// 编号与目的地去掉首尾空白后不得为空，weight 必须为正整数（千克）。
// 货物登记后处于未装载状态。
// 编号按去空白后的值识别并区分大小写；重复登记保留原记录。
func (r *Registry) RegisterCargo(id string, weight int64, destination string, allowMixed bool) error {
	r.mu.Lock()
	defer r.mu.Unlock()

	cid := strings.TrimSpace(id)
	if cid == "" {
		return fail(ErrInvalidID, "", "货物编号为空")
	}
	if weight <= 0 {
		return fail(ErrInvalidWeight, cid, "货物 %s 重量必须为正整数千克，当前为 %d", cid, weight)
	}
	dest := strings.TrimSpace(destination)
	if dest == "" {
		return fail(ErrInvalidDestination, cid, "货物 %s 目的地为空", cid)
	}
	if _, exists := r.cargos[cid]; exists {
		return fail(ErrAlreadyExists, cid, "货物 %s 已存在", cid)
	}
	r.cargos[cid] = &cargo{
		id:          cid,
		weight:      weight,
		destination: dest,
		allowMixed:  allowMixed,
	}
	return nil
}

// Compartment 查询舱位的承重、已用重量、剩余重量与货物清单。
// 编号去掉首尾空白后识别；不存在时返回错误。
func (r *Registry) Compartment(id string) (*CompartmentView, error) {
	r.mu.Lock()
	defer r.mu.Unlock()

	cid := strings.TrimSpace(id)
	if cid == "" {
		return nil, fail(ErrInvalidID, "", "舱位编号为空")
	}
	comp, ok := r.compartments[cid]
	if !ok {
		return nil, fail(ErrNotFound, cid, "舱位 %s 不存在", cid)
	}
	view := compartmentView(comp)
	return &view, nil
}

// Cargo 查询货物的当前舱位或未装载状态。
// 编号去掉首尾空白后识别；不存在时返回错误。
func (r *Registry) Cargo(id string) (*CargoView, error) {
	r.mu.Lock()
	defer r.mu.Unlock()

	cid := strings.TrimSpace(id)
	if cid == "" {
		return nil, fail(ErrInvalidID, "", "货物编号为空")
	}
	c, ok := r.cargos[cid]
	if !ok {
		return nil, fail(ErrNotFound, cid, "货物 %s 不存在", cid)
	}
	return cargoView(c), nil
}

// sumSet 合计一组货物的重量（调用方持锁）。
func sumSet(set map[string]*cargo) int64 {
	var sum int64
	for _, c := range set {
		sum += c.weight
	}
	return sum
}

// cloneResult 复制一份调整结果，避免调用方修改影响已保存的快照。
func cloneResult(r *AdjustmentResult) *AdjustmentResult {
	return &AdjustmentResult{
		ID:                 r.ID,
		CargoChanges:       append([]CargoChange(nil), r.CargoChanges...),
		CompartmentChanges: append([]CompartmentChange(nil), r.CompartmentChanges...),
	}
}

package stowage

import (
	"math"
	"sort"
)

// cargoView 构造货物快照，重量、目的地与混装许可取登记资料（调用方持锁）。
func cargoView(c *cargo) *CargoView {
	return &CargoView{
		ID:            c.id,
		Weight:        c.weight,
		Destination:   c.destination,
		AllowMixed:    c.allowMixed,
		Loaded:        c.compartmentID != "",
		CompartmentID: c.compartmentID,
	}
}

// compartmentSnapshot 按给定货物集合生成舱位配载快照，是查询实际配载与
// 预览预计配载共用的组装入口：清单按货物编号字典序排列，包含集合中的
// 全部货物；每件货物的重量、目的地与混装许可取登记资料。
//
// projected 为 false 时清单保留货物的真实装载状态与所属舱位（实际配载）；
// 为 true 时一律显示为已装载且属于该舱位（预计配载）。重量合计溢出
// int64 时，已用与剩余重量不提供数值（保持零值），货物清单照常返回。
// 调用方持锁。
func compartmentSnapshot(comp *compartment, set map[string]*cargo, projected bool) CompartmentView {
	ids := make([]string, 0, len(set))
	for cid := range set {
		ids = append(ids, cid)
	}
	sort.Strings(ids)
	views := make([]CargoView, 0, len(ids))
	var used int64
	overflow := false
	for _, cid := range ids {
		c := set[cid]
		view := *cargoView(c)
		if projected {
			// 预计清单中的货物按模拟配载完成后的所属舱位展示；cargoView
			// 返回的是值副本，改写位置字段不影响登记处。
			view.Loaded = true
			view.CompartmentID = comp.id
		}
		views = append(views, view)
		if !overflow {
			if c.weight > math.MaxInt64-used {
				overflow = true
			} else {
				used += c.weight
			}
		}
	}
	view := CompartmentView{
		ID:        comp.id,
		MaxWeight: comp.maxWeight,
		Cargo:     views,
	}
	if !overflow {
		view.UsedWeight = used
		view.RemainingWeight = comp.maxWeight - used
	}
	return view
}

// compartmentView 生成舱位当前实际配载的快照（调用方持锁）。
func compartmentView(comp *compartment) CompartmentView {
	return compartmentSnapshot(comp, comp.cargo, false)
}

// compartmentAfterView 生成舱位在模拟配载下的预计快照（调用方持锁）。
func compartmentAfterView(comp *compartment, set map[string]*cargo) CompartmentView {
	return compartmentSnapshot(comp, set, true)
}

// OpKind 表示调整操作的种类。
type OpKind int

const (
	// OpLoad 装载：将未装载的货物装入目标舱位。
	OpLoad OpKind = iota
	// OpUnload 卸下：将已装载的货物从当前舱位移除，货物记录保留。
	OpUnload
	// OpMove 移动：将已装载的货物直接改放到目标舱位。
	OpMove
)

// String 返回操作种类名称。
func (k OpKind) String() string {
	switch k {
	case OpLoad:
		return "装载"
	case OpUnload:
		return "卸下"
	case OpMove:
		return "移动"
	default:
		return "未知"
	}
}

// Op 是一次调整中的单个操作。
type Op struct {
	Kind    OpKind
	CargoID string
	Target  string // 装载/移动时的目标舱位；卸下时忽略
}

// CargoChange 记录一件货物调整前后的所属舱位。
type CargoChange struct {
	CargoID string
	From    string // 空字符串表示未装载
	To      string // 空字符串表示未装载
}

// CompartmentChange 记录一个舱位调整前后的总重量。
type CompartmentChange struct {
	CompartmentID string
	WeightBefore  int64
	WeightAfter   int64
}

// AdjustmentResult 是一次成功调整的结果快照。
type AdjustmentResult struct {
	ID                 string
	CargoChanges       []CargoChange
	CompartmentChanges []CompartmentChange
}

// CargoView 是货物信息的独立快照。
type CargoView struct {
	ID            string
	Weight        int64
	Destination   string
	AllowMixed    bool
	Loaded        bool
	CompartmentID string // 空字符串表示未装载
}

// CompartmentView 是舱位信息的独立快照。
type CompartmentView struct {
	ID              string
	MaxWeight       int64
	UsedWeight      int64
	RemainingWeight int64
	Cargo           []CargoView // 按编号字典序排列
}

// MixedDestination 描述预计配载中一个舱位内某个目的地对应的全部货物。
type MixedDestination struct {
	Destination string
	CargoIDs    []string // 按编号字典序排列
}

// Rejection 描述预计配载中单个舱位的一条拒绝原因。
//
// Kind 为 ErrOverweight 时，UsedWeight、RemainingWeight、Overweight 与
// MaxWeight 均有效；Kind 为 ErrOverflow（重量溢出）时，预计已用重量、
// 剩余重量与超出量无法用 int64 表示，对应数值字段保持零值，仅提供
// MaxWeight、货物清单与混装原因；Kind 为 ErrMixedLoading 时，
// Destinations 给出各目的地对应的货物，OffendingCargo 列出其中全部
// 不允许混装的货物编号。
type Rejection struct {
	CompartmentID   string
	Kind            ErrorKind
	MaxWeight       int64
	UsedWeight      int64              // 超重时为预计总重量；溢出或混装时为零值
	RemainingWeight int64              // 超重时为预计剩余重量（负值）；其余为零值
	Overweight      int64              // 超重时为超出承重的千克数；其余为零值
	Destinations    []MixedDestination // 混装冲突时各目的地及其货物，按目的地字典序排列
	OffendingCargo  []string           // 混装冲突时全部不允许混装的货物编号，字典序排列
}

// CompartmentPreview 是受影响舱位调整前后的完整配载快照。
// Before 反映调整前配载，清单中的货物保持原所属舱位；After 反映预计
// 配载，清单中的货物一律显示为已装载且属于该舱位，编号、重量、目的地
// 与混装许可仍取登记资料。预计超重时 RemainingWeight 为负值；预计重量
// 溢出 int64 时 After 不提供已用与剩余重量数值（保持零值），货物清单
// 照常返回。
type CompartmentPreview struct {
	ID     string
	Before CompartmentView
	After  CompartmentView
}

// PreviewResult 是一次预览的完整结果，本身是与登记处状态无关的独立快照。
type PreviewResult struct {
	// Submittable 表示按当前登记处状态，这组操作能否作为一次调整提交。
	Submittable bool
	// CargoChanges 列出清单涉及货物的原舱位与预计舱位，按货物编号字典序排列；
	// 未装载用空编号表示。
	CargoChanges []CargoChange
	// Compartments 列出全部受影响舱位调整前后的完整货物清单、已用重量与
	// 剩余重量，按舱位编号字典序排列。即使交换后总重量不变也会列出。
	Compartments []CompartmentPreview
	// Rejections 列出预计配载的全部拒绝原因，按舱位编号排列，同一舱位
	// 先重量（超重/溢出）后混装。为空表示 Submittable 为 true。
	Rejections []Rejection
}

package stowage_test

import (
	"errors"
	"fmt"

	"github.com/descikazuyq/cargo-stowage/stowage"
)

// newSwapRegistry 新建登记处并完成初始配载：两个承重均为 30 千克的舱位，
// 各装入一件 30 千克、目的地相同且不允许混装的货物。每个示例都从这里
// 独立开始，不依赖其他示例留下的状态。
func newSwapRegistry() *stowage.Registry {
	reg := stowage.NewRegistry()
	must := func(err error) {
		if err != nil {
			panic(err)
		}
	}
	must(reg.RegisterCompartment("C1", 30))
	must(reg.RegisterCompartment("C2", 30))
	must(reg.RegisterCargo("G1", 30, "上海", false))
	must(reg.RegisterCargo("G2", 30, "上海", false))
	_, err := reg.Adjust("load-1", []stowage.Op{
		{Kind: stowage.OpLoad, CargoID: "G1", Target: "C1"},
		{Kind: stowage.OpLoad, CargoID: "G2", Target: "C2"},
	})
	must(err)
	return reg
}

// cargoIDs 提取舱位快照中的货物编号清单。
func cargoIDs(v stowage.CompartmentView) []string {
	ids := make([]string, 0, len(v.Cargo))
	for _, c := range v.Cargo {
		ids = append(ids, c.ID)
	}
	return ids
}

// 预览同一批安排中的两件货物互换：两个舱位各自满载，但限制按整批安排
// 完成后的最终配载判断，交换后每个舱位仍恰好在承重内，因此可以提交。
func Example_previewSwap() {
	reg := newSwapRegistry()

	res, err := reg.Preview([]stowage.Op{
		{Kind: stowage.OpMove, CargoID: "G1", Target: "C2"},
		{Kind: stowage.OpMove, CargoID: "G2", Target: "C1"},
	})
	if err != nil {
		panic(err)
	}

	fmt.Println("可提交:", res.Submittable)
	for _, ch := range res.CargoChanges {
		fmt.Printf("货物 %s: %s -> %s\n", ch.CargoID, ch.From, ch.To)
	}
	// 即使交换后总重量不变，两个舱位仍会列出前后的完整货物清单。
	for _, cp := range res.Compartments {
		fmt.Printf("舱位 %s 前: %v（%d/%d 千克）\n",
			cp.ID, cargoIDs(cp.Before), cp.Before.UsedWeight, cp.Before.MaxWeight)
		fmt.Printf("舱位 %s 后: %v（%d/%d 千克）\n",
			cp.ID, cargoIDs(cp.After), cp.After.UsedWeight, cp.After.MaxWeight)
	}
	// 预计清单中的货物位置按交换后的所属舱位解释。
	fmt.Printf("预计清单中 %s 属于舱位 %s\n",
		res.Compartments[0].After.Cargo[0].ID,
		res.Compartments[0].After.Cargo[0].CompartmentID)

	// 预览是只读的：查询当前货物仍看到交换前的位置。
	g1, _ := reg.Cargo("G1")
	fmt.Println("预览后查询 G1 所在舱位:", g1.CompartmentID)

	// Output:
	// 可提交: true
	// 货物 G1: C1 -> C2
	// 货物 G2: C2 -> C1
	// 舱位 C1 前: [G1]（30/30 千克）
	// 舱位 C1 后: [G2]（30/30 千克）
	// 舱位 C2 前: [G2]（30/30 千克）
	// 舱位 C2 后: [G1]（30/30 千克）
	// 预计清单中 G2 属于舱位 C1
	// 预览后查询 G1 所在舱位: C1
}

// 预览一组会被拒绝的安排：向已满载的 C1 装入第三件货物（10 千克、目的地
// 不同、允许混装）。每条操作本身合法，预览照常返回预计清单，但
// Submittable 为 false，且同时列出超重与混装冲突两条拒绝原因。
func Example_previewRejected() {
	reg := newSwapRegistry()
	if err := reg.RegisterCargo("G3", 10, "北京", true); err != nil {
		panic(err)
	}

	res, err := reg.Preview([]stowage.Op{
		{Kind: stowage.OpLoad, CargoID: "G3", Target: "C1"},
	})
	// 操作本身合法，预览调用不失败；不可提交体现在结果里。
	fmt.Println("预览调用出错:", err != nil)
	fmt.Println("可提交:", res.Submittable)
	for _, cp := range res.Compartments {
		fmt.Printf("舱位 %s 后: %v（%d/%d 千克）\n",
			cp.ID, cargoIDs(cp.After), cp.After.UsedWeight, cp.After.MaxWeight)
	}
	for _, rej := range res.Rejections {
		switch rej.Kind {
		case stowage.ErrOverweight:
			fmt.Printf("舱位 %s 超重 %d 千克（%d/%d）\n",
				rej.CompartmentID, rej.Overweight, rej.UsedWeight, rej.MaxWeight)
		case stowage.ErrMixedLoading:
			for _, d := range rej.Destinations {
				fmt.Printf("舱位 %s 目的地 %s: %v\n", rej.CompartmentID, d.Destination, d.CargoIDs)
			}
			fmt.Printf("不允许混装的货物: %v\n", rej.OffendingCargo)
		}
	}

	// 被拒绝的预览同样不改变配载。
	c1, _ := reg.Compartment("C1")
	fmt.Println("预览后 C1 实际货物:", cargoIDs(*c1))

	// Output:
	// 预览调用出错: false
	// 可提交: false
	// 舱位 C1 后: [G1 G3]（40/30 千克）
	// 舱位 C1 超重 10 千克（40/30）
	// 舱位 C1 目的地 上海: [G1]
	// 舱位 C1 目的地 北京: [G3]
	// 不允许混装的货物: [G1]
	// 预览后 C1 实际货物: [G1]
}

// 操作本身不合法（货物编号不存在）时，预览返回结构化错误且没有局部
// 预览，与“操作合法但最终配载不可提交”的拒绝结果不同。
func Example_previewInvalidOp() {
	reg := newSwapRegistry()

	res, err := reg.Preview([]stowage.Op{
		{Kind: stowage.OpLoad, CargoID: "G9", Target: "C1"},
	})
	fmt.Println("有预览结果:", res != nil)
	var serr *stowage.Error
	if errors.As(err, &serr) {
		fmt.Println("错误原因:", serr.Kind)
		fmt.Println("涉及编号:", serr.ID)
	}

	// Output:
	// 有预览结果: false
	// 错误原因: 对象不存在
	// 涉及编号: G9
}

// 预览通过后用同一批操作正式提交：只有 Adjust 成功才应用安排，此后的
// 查询结果与之前的预计配载对应。
func Example_adjustAfterPreview() {
	reg := newSwapRegistry()

	ops := []stowage.Op{
		{Kind: stowage.OpMove, CargoID: "G1", Target: "C2"},
		{Kind: stowage.OpMove, CargoID: "G2", Target: "C1"},
	}
	res, err := reg.Preview(ops)
	if err != nil {
		panic(err)
	}
	fmt.Println("预览可提交:", res.Submittable)

	// 预览本身不改变配载，也不占用调整编号；正式提交才应用安排。
	adj, err := reg.Adjust("swap-1", ops)
	if err != nil {
		panic(err)
	}
	fmt.Println("已提交调整:", adj.ID)
	g1, _ := reg.Cargo("G1")
	g2, _ := reg.Cargo("G2")
	fmt.Println("提交后 G1 所在舱位:", g1.CompartmentID)
	fmt.Println("提交后 G2 所在舱位:", g2.CompartmentID)

	// Output:
	// 预览可提交: true
	// 已提交调整: swap-1
	// 提交后 G1 所在舱位: C2
	// 提交后 G2 所在舱位: C1
}

package stowage_test

import (
	"errors"
	"fmt"

	"github.com/descikazuyq/cargo-stowage/stowage"
)

// newAmendRegistry 新建登记处并完成初始配载：舱位 C1 承重 100 千克，装入
// 两件目的地不同、都允许混装的货物（G1 30 千克去上海、G2 20 千克去北京），
// 已用 50 千克。每个示例都从这里独立开始，不依赖其他示例留下的状态。
func newAmendRegistry() *stowage.Registry {
	reg := stowage.NewRegistry()
	must := func(err error) {
		if err != nil {
			panic(err)
		}
	}
	must(reg.RegisterCompartment("C1", 100))
	must(reg.RegisterCargo("G1", 30, "上海", true))
	must(reg.RegisterCargo("G2", 20, "北京", true))
	_, err := reg.Adjust("load-1", []stowage.Op{
		{Kind: stowage.OpLoad, CargoID: "G1", Target: "C1"},
		{Kind: stowage.OpLoad, CargoID: "G2", Target: "C1"},
	})
	must(err)
	return reg
}

// 更正已装载货物 G2 的三项资料：重量 20 -> 40 千克、目的地 北京 -> 上海
// （与同舱 G1 相同）、同时取消混装许可。三项作为一次整体替换生效，货物
// 编号与所属舱位不变；目的地一致后同舱共载不再要求混装许可。
func Example_amendLoadedCargo() {
	reg := newAmendRegistry()

	show := func(label string) {
		g2, _ := reg.Cargo("G2")
		c1, _ := reg.Compartment("C1")
		fmt.Printf("%s: G2 重量 %d 千克、目的地 %s、允许混装 %t、所在舱位 %s\n",
			label, g2.Weight, g2.Destination, g2.AllowMixed, g2.CompartmentID)
		fmt.Printf("%s: 舱位 C1 已用 %d 千克、剩余 %d 千克\n",
			label, c1.UsedWeight, c1.RemainingWeight)
	}
	show("更正前")

	// 三项资料一次整体替换：重量、目的地、混装许可。
	err := reg.AmendCargo("G2", 40, "上海", false)
	fmt.Println("更正返回错误:", err)

	show("更正后")

	// Output:
	// 更正前: G2 重量 20 千克、目的地 北京、允许混装 true、所在舱位 C1
	// 更正前: 舱位 C1 已用 50 千克、剩余 50 千克
	// 更正返回错误: <nil>
	// 更正后: G2 重量 40 千克、目的地 上海、允许混装 false、所在舱位 C1
	// 更正后: 舱位 C1 已用 70 千克、剩余 30 千克
}

// 更正后的新重量使当前舱位超重时被拒绝：G1 改到 90 千克后舱位预计合计
// 110 千克，超过承重 100 千克。失败后旧资料、装载位置与舱位重量全部保留。
func Example_amendOverweightRejected() {
	reg := newAmendRegistry()

	err := reg.AmendCargo("G1", 90, "上海", true)
	var serr *stowage.Error
	if errors.As(err, &serr) {
		fmt.Println("拒绝原因:", serr.Kind)
		fmt.Println("涉及编号:", serr.ID)
		fmt.Println("说明:", serr)
	}

	// 失败后查询：三项旧资料、装载位置与舱位重量全部保留。
	g1, _ := reg.Cargo("G1")
	c1, _ := reg.Compartment("C1")
	fmt.Printf("G1 仍是 %d 千克、目的地 %s、允许混装 %t、所在舱位 %s\n",
		g1.Weight, g1.Destination, g1.AllowMixed, g1.CompartmentID)
	fmt.Printf("舱位 C1 已用 %d 千克、剩余 %d 千克\n", c1.UsedWeight, c1.RemainingWeight)

	// Output:
	// 拒绝原因: 超重
	// 涉及编号: C1
	// 说明: 舱位 C1 总重量 110 千克超过最大承重 100 千克
	// G1 仍是 30 千克、目的地 上海、允许混装 true、所在舱位 C1
	// 舱位 C1 已用 50 千克、剩余 50 千克
}

// 目的地仍不同（上海/北京）时取消 G1 的混装许可被拒绝：不同目的地共舱
// 要求所有货物都允许混装。失败后旧资料、装载位置与舱位重量全部保留。
func Example_amendMixedConflictRejected() {
	reg := newAmendRegistry()

	err := reg.AmendCargo("G1", 30, "上海", false)
	var serr *stowage.Error
	if errors.As(err, &serr) {
		fmt.Println("拒绝原因:", serr.Kind)
		fmt.Println("涉及编号:", serr.ID)
		fmt.Println("说明:", serr)
	}

	// 失败后查询：三项旧资料、装载位置与舱位重量全部保留。
	g1, _ := reg.Cargo("G1")
	c1, _ := reg.Compartment("C1")
	fmt.Printf("G1 仍是 %d 千克、目的地 %s、允许混装 %t、所在舱位 %s\n",
		g1.Weight, g1.Destination, g1.AllowMixed, g1.CompartmentID)
	fmt.Printf("舱位 C1 已用 %d 千克、剩余 %d 千克\n", c1.UsedWeight, c1.RemainingWeight)

	// Output:
	// 拒绝原因: 混装冲突
	// 涉及编号: G1
	// 说明: 舱位 C1 存在不同目的地货物，但货物 G1 不允许混装
	// G1 仍是 30 千克、目的地 上海、允许混装 true、所在舱位 C1
	// 舱位 C1 已用 50 千克、剩余 50 千克
}

// 更正后舱位承重恰好用满是允许的，不算超重：G2 改到 70 千克后舱位合计
// 恰好 100 千克，等于承重，更正成功。
func Example_amendExactCapacity() {
	reg := newAmendRegistry()

	err := reg.AmendCargo("G2", 70, "北京", true)
	fmt.Println("更正返回错误:", err)
	c1, _ := reg.Compartment("C1")
	fmt.Printf("舱位 C1 已用 %d 千克、剩余 %d 千克\n", c1.UsedWeight, c1.RemainingWeight)

	// Output:
	// 更正返回错误: <nil>
	// 舱位 C1 已用 100 千克、剩余 0 千克
}

// Package stowage 提供本地舱单与配载能力：
// 登记舱位与货物、执行多货物的装卸调整、预览调整结果、更正货物资料，
// 并可随时查询配载状态。
//
// 舱位以唯一编号和最大承重（正整数千克）标识；货物以唯一编号、
// 重量（正整数千克）、目的地及是否允许混装标识。货物登记后处于
// 未装载状态，可通过调整进行装载、卸下或移动。AmendCargo 可在货物
// 编号与所属舱位不变的前提下整体替换其重量、目的地与混装许可；已
// 装载货物按三项资料共同生效后的最终配载校验，更正不占用调整编号。
//
// 一次调整可包含多件货物的操作，全部操作按完成后的最终配载统一
// 校验：舱位总重量不得超过承重；不同目的地货物共舱时所有货物都
// 必须允许混装。任一操作不合法，整次调整不生效。
//
// Preview 在不改变任何状态的前提下预演同一批操作，给出能否提交、
// 涉及货物的原舱位与预计舱位、受影响舱位前后完整配载，以及全部
// 拒绝原因；正式提交仍以 Adjust 提交时的状态重新判断。
package stowage

// Ready 表示基线可以运行。
func Ready() bool { return true }

