1	package stowage
2	
3	import (
4		"errors"
5		"math"
6		"reflect"
7		"strings"
8		"testing"
9	)
10	
11	// 本文件为正式提交（Adjust）补充回归保障：一批安排在多个舱位同时触发
12	// 重量与混装限制时，正式提交只返回一个结构化错误，报告顺序固定为
13	// 先按舱位编号字典序选最靠前的违规舱位、同一舱位先重量后混装；被拒绝
14	// 后原配载可完整回查（整批原子性）；并保护 Preview（列全拒绝原因）与
15	// Adjust（只报一个）两种入口各自的用途。
16	
17	// ---------- 测试辅助 ----------
18	
19	func mustRegisterCompartment(t *testing.T, r *Registry, id string, maxWeight int64) {
20		t.Helper()
21		if err := r.RegisterCompartment(id, maxWeight); err != nil {
22			t.Fatalf("登记舱位 %s 失败: %v", id, err)
23		}
24	}
25	
26	func mustRegisterCargo(t *testing.T, r *Registry, id string, weight int64, dest string, mixed bool) {
27		t.Helper()
28		if err := r.RegisterCargo(id, weight, dest, mixed); err != nil {
29			t.Fatalf("登记货物 %s 失败: %v", id, err)
30		}
31	}
32	
33	// submitExpectReject 提交并断言调整被拒绝：err 为单条 *Error，且不返回
34	// 成功结果。返回该结构化错误供调用方核对 Kind、ID、AdjustmentID 与说明。
35	func submitExpectReject(t *testing.T, r *Registry, id string, ops []Op) *Error {
36		t.Helper()
37		res, err := r.Adjust(id, ops)
38		if err == nil {
39			t.Fatalf("调整 %s 应被拒绝，却返回成功: %+v", id, res)
40		}
41		if res != nil {
42			t.Fatalf("被拒绝的调整不应返回成功结果: %+v", res)
43		}
44		var se *Error
45		if !errors.As(err, &se) {
46			t.Fatalf("期望 *Error，实际为 %T: %v", err, err)
47		}
48		return se
49	}
50	
51	// snapshotCompartments 对指定舱位做提交前快照（完整清单、已用与剩余重量）。
52	func snapshotCompartments(r *Registry, ids ...string) map[string]CompartmentView {
53		snap := make(map[string]CompartmentView, len(ids))
54		for _, id := range ids {
55			v, err := r.Compartment(id)
56			if err != nil {
57				panic(err)
58			}
59			snap[id] = *v
60		}
61		return snap
62	}
63	
64	// snapshotCargo 对给定货物做提交前快照（重量、目的地、混装许可、归属）。
65	func snapshotCargo(r *Registry, ids ...string) map[string]CargoView {
66		snap := make(map[string]CargoView, len(ids))
67		for _, id := range ids {
68			v, err := r.Cargo(id)
69			if err != nil {
70				panic(err)
71			}
72			snap[id] = *v
73		}
74		return snap
75	}
76	
77	// assertCompartmentsUnchanged 对比提交前快照与拒绝后查询结果。
78	func assertCompartmentsUnchanged(t *testing.T, r *Registry, before map[string]CompartmentView) {
79		t.Helper()
80		for id, want := range before {
81			got, err := r.Compartment(id)
82			if err != nil {
83				t.Fatalf("查询舱位 %s 失败: %v", id, err)
84			}
85			if got.MaxWeight != want.MaxWeight ||
86				got.UsedWeight != want.UsedWeight ||
87				got.RemainingWeight != want.RemainingWeight ||
88				!reflect.DeepEqual(cargoIDs(*got), cargoIDs(want)) {
89				t.Fatalf("舱位 %s 在拒绝后改变: 提交前 %+v, 提交后 %+v", id, want, got)
90			}
91		}
92	}
93	
94	// assertCargoUnchanged 对比提交前货物快照与拒绝后查询结果（含登记资料
95	// 与装载状态）。
96	func assertCargoUnchanged(t *testing.T, r *Registry, before map[string]CargoView) {
97		t.Helper()
98		for id, want := range before {
99			got, err := r.Cargo(id)
100			if err != nil {
101				t.Fatalf("查询货物 %s 失败: %v", id, err)
102			}
103			if got.Weight != want.Weight ||
104				got.Destination != want.Destination ||
105				got.AllowMixed != want.AllowMixed ||
106				got.Loaded != want.Loaded ||
107				got.CompartmentID != want.CompartmentID {
108				t.Fatalf("货物 %s 在拒绝后改变: 提交前 %+v, 提交后 %+v", id, want, got)
109			}
110		}
111	}
112	
113	// assertAllEmpty 确认四件货物都未装载、两个舱位都是空舱。
114	func assertAllEmpty(t *testing.T, r *Registry) {
115		t.Helper()
116		for _, id := range []string{"G1", "G2", "G3", "G4"} {
117			c, _ := r.Cargo(id)
118			if c.Loaded || c.CompartmentID != "" {
119				t.Fatalf("货物 %s 应仍未装载，实际在 %q", id, c.CompartmentID)
120			}
121		}
122		for _, id := range []string{"C1", "C2"} {
123			cpt, _ := r.Compartment(id)
124			if cpt.UsedWeight != 0 || cpt.RemainingWeight != cpt.MaxWeight || len(cpt.Cargo) != 0 {
125				t.Fatalf("舱位 %s 应仍为空舱，实际 %+v", id, cpt)
126			}
127		}
128	}
129	
130	// ---------- 跨舱位报告对象选择 ----------
131	
132	// C1 仅混装冲突、C2 仅超重时，必须报告字典序最靠前的 C1 的混装冲突，
133	// 错误对象为 C1 内不允许混装且编号最靠前的货物，说明指出冲突舱位。
134	func TestAdjustReportsLexicographicallyEarliestCompartment(t *testing.T) {
135		r := NewRegistry()
136		mustRegisterCompartment(t, r, "C1", 1000)
137		mustRegisterCompartment(t, r, "C2", 50)
138		// C1 最终：G1（上海，不许混装）+ G2（北京，允许）-> 仅混装冲突。
139		mustRegisterCargo(t, r, "G1", 10, "上海", false)
140		mustRegisterCargo(t, r, "G2", 10, "北京", true)
141		// C2 最终：G3+G4 共 60 > 50 -> 仅超重，同目的地不构成混装冲突。
142		mustRegisterCargo(t, r, "G3", 30, "X", true)
143		mustRegisterCargo(t, r, "G4", 30, "X", true)
144	
145		ops := []Op{
146			{Kind: OpLoad, CargoID: "G4", Target: "C2"},
147			{Kind: OpLoad, CargoID: "G3", Target: "C2"},
148			{Kind: OpLoad, CargoID: "G2", Target: "C1"},
149			{Kind: OpLoad, CargoID: "G1", Target: "C1"},
150		}
151		se := submitExpectReject(t, r, "  adj-1  ", ops)
152		if se.Kind != ErrMixedLoading || se.ID != "G1" {
153			t.Fatalf("应报告 C1 的混装冲突并指出 G1，实际 Kind=%s ID=%q", se.Kind, se.ID)
154		}
155		if !strings.Contains(se.Error(), "C1") {
156			t.Fatalf("混装说明应指出冲突舱位 C1: %s", se.Error())
157		}
158		// 调整编号去掉首尾空白后携带。
159		if se.AdjustmentID != "adj-1" {
160			t.Fatalf("错误应携带去空白后的调整编号 adj-1，实际 %q", se.AdjustmentID)
161		}
162		assertAllEmpty(t, r)
163	}
164	
165	// 无论 C2 的操作放在清单前面还是后面，报告结果都是 C1 的混装冲突。
166	func TestAdjustReportStableAcrossOpOrder(t *testing.T) {
167		build := func() (*Registry, []Op) {
168			r := NewRegistry()
169			mustRegisterCompartment(t, r, "C1", 1000)
170			mustRegisterCompartment(t, r, "C2", 50)
171			mustRegisterCargo(t, r, "G1", 10, "上海", false)
172			mustRegisterCargo(t, r, "G2", 10, "北京", true)
173			mustRegisterCargo(t, r, "G3", 30, "X", true)
174			mustRegisterCargo(t, r, "G4", 30, "X", true)
175			ops := []Op{
176				{Kind: OpLoad, CargoID: "G4", Target: "C2"},
177				{Kind: OpLoad, CargoID: "G3", Target: "C2"},
178				{Kind: OpLoad, CargoID: "G2", Target: "C1"},
179				{Kind: OpLoad, CargoID: "G1", Target: "C1"},
180			}
181			return r, ops
182		}
183	
184		// C2 的操作在前。
185		r, _ := build()
186		se := submitExpectReject(t, r, "adj-1", []Op{
187			{Kind: OpLoad, CargoID: "G3", Target: "C2"},
188			{Kind: OpLoad, CargoID: "G4", Target: "C2"},
189			{Kind: OpLoad, CargoID: "G1", Target: "C1"},
190			{Kind: OpLoad, CargoID: "G2", Target: "C1"},
191		})
192		if se.Kind != ErrMixedLoading || se.ID != "G1" {
193			t.Fatalf("C2 操作在前时仍应报告 C1 混装冲突，实际 Kind=%s ID=%q", se.Kind, se.ID)
194		}
195		assertAllEmpty(t, r)
196	
197		// C1 的操作在前。
198		r, _ = build()
199		se = submitExpectReject(t, r, "adj-1", []Op{
200			{Kind: OpLoad, CargoID: "G1", Target: "C1"},
201			{Kind: OpLoad, CargoID: "G2", Target: "C1"},
202			{Kind: OpLoad, CargoID: "G3", Target: "C2"},
203			{Kind: OpLoad, CargoID: "G4", Target: "C2"},
204		})
205		if se.Kind != ErrMixedLoading || se.ID != "G1" {
206			t.Fatalf("C1 操作在前时仍应报告 C1 混装冲突，实际 Kind=%s ID=%q", se.Kind, se.ID)
207		}
208		assertAllEmpty(t, r)
209	}
210	
211	// 改变舱位与货物的登记次序，不能改变按编号字典序得到的报告结果。
212	func TestAdjustReportStableAcrossRegistrationOrder(t *testing.T) {
213		// 登记次序：先 C2 后 C1；货物先登记涉及 C2 的 G4、G3，再 C1 的 G2、G1。
214		r := NewRegistry()
215		mustRegisterCompartment(t, r, "C2", 50)
216		mustRegisterCompartment(t, r, "C1", 1000)
217		mustRegisterCargo(t, r, "G4", 30, "X", true)
218		mustRegisterCargo(t, r, "G3", 30, "X", true)
219		mustRegisterCargo(t, r, "G2", 10, "北京", true)
220		mustRegisterCargo(t, r, "G1", 10, "上海", false)
221	
222		se := submitExpectReject(t, r, "adj-x", []Op{
223			{Kind: OpLoad, CargoID: "G3", Target: "C2"},
224			{Kind: OpLoad, CargoID: "G4", Target: "C2"},
225			{Kind: OpLoad, CargoID: "G1", Target: "C1"},
226			{Kind: OpLoad, CargoID: "G2", Target: "C1"},
227		})
228		if se.Kind != ErrMixedLoading || se.ID != "G1" {
229			t.Fatalf("改变登记次序后仍应报告 C1 混装冲突（G1），实际 Kind=%s ID=%q", se.Kind, se.ID)
230		}
231		assertAllEmpty(t, r)
232	}
233	
234	// 除 C1、C2 外还有一个字典序更靠后、同样违规的舱位时，仍只报 C1。
235	func TestAdjustEarliestCompartmentAmongThree(t *testing.T) {
236		r := NewRegistry()
237		mustRegisterCompartment(t, r, "C1", 1000)
238		mustRegisterCompartment(t, r, "C2", 50)
239		mustRegisterCompartment(t, r, "C3", 50)
240		mustRegisterCargo(t, r, "G1", 10, "上海", false)
241		mustRegisterCargo(t, r, "G2", 10, "北京", true) // C1：仅混装
242		mustRegisterCargo(t, r, "G3", 60, "X", true)  // C2：超重
243		mustRegisterCargo(t, r, "G5", 60, "X", true)  // C3：超重
244		se := submitExpectReject(t, r, "adj-3", []Op{
245			{Kind: OpLoad, CargoID: "G5", Target: "C3"},
246			{Kind: OpLoad, CargoID: "G3", Target: "C2"},
247			{Kind: OpLoad, CargoID: "G2", Target: "C1"},
248			{Kind: OpLoad, CargoID: "G1", Target: "C1"},
249		})
250		if se.Kind != ErrMixedLoading || se.ID != "G1" {
251			t.Fatalf("三个舱位同时违规时仍应只报 C1 混装冲突，实际 Kind=%s ID=%q", se.Kind, se.ID)
252		}
253		for _, c := range []string{"C1", "C2", "C3"} {
254			v, _ := r.Compartment(c)
255			if v.UsedWeight != 0 || len(v.Cargo) != 0 {
256				t.Fatalf("舱位 %s 应仍为空舱: %+v", c, v)
257			}
258		}
259	}
260	
261	// ---------- 同一舱位两种原因的取舍 ----------
262	
263	// 同一舱位同时超重与混装冲突时，先报告重量原因：错误对象是舱位本身，
264	// 说明里能看到预计总重量与最大承重。
265	func TestAdjustSameCompartmentWeightBeforeMixed(t *testing.T) {
266		r := NewRegistry()
267		mustRegisterCompartment(t, r, "C1", 50)
268		// G1（上海，不许混装）+ G2（北京，允许）最终共 100 > 50，且混装冲突。
269		mustRegisterCargo(t, r, "G1", 60, "上海", false)
270		mustRegisterCargo(t, r, "G2", 40, "北京", true)
271	
272		se := submitExpectReject(t, r, "adj-wm", []Op{
273			{Kind: OpLoad, CargoID: "G2", Target: "C1"},
274			{Kind: OpLoad, CargoID: "G1", Target: "C1"},
275		})
276		if se.Kind != ErrOverweight {
277			t.Fatalf("同舱超重与混装并存时应先报重量，实际 Kind=%s", se.Kind)
278		}
279		// 错误对象编号是该舱位，而不是任何一件货物。
280		if se.ID != "C1" {
281			t.Fatalf("重量原因应指向舱位 C1，实际 ID=%q", se.ID)
282		}
283		// 说明里能看到预计总重量与最大承重。
284		if !strings.Contains(se.Error(), "100") || !strings.Contains(se.Error(), "50") {
285			t.Fatalf("超重说明应包含预计总重量 100 与最大承重 50: %s", se.Error())
286		}
287		if se.AdjustmentID != "adj-wm" {
288			t.Fatalf("错误应携带调整编号 adj-wm，实际 %q", se.AdjustmentID)
289		}
290		cpt, _ := r.Compartment("C1")
291		if cpt.UsedWeight != 0 || cpt.RemainingWeight != 50 || len(cpt.Cargo) != 0 {
292			t.Fatalf("C1 应仍为空舱: %+v", cpt)
293		}
