func TestAtomicFailureRollsBack(t *testing.T) {
	r := NewRegistry()
	if err := r.RegisterCompartment("C1", 100); err != nil {
		t.Fatal(err)
	}
	if err := r.RegisterCompartment("C2", 100); err != nil {
		t.Fatal(err)
	}
	if err := r.RegisterCargo("G1", 60, "X", true); err != nil {
		t.Fatal(err)
	}
	if err := r.RegisterCargo("G2", 50, "X", true); err != nil {
		t.Fatal(err)
	}
	if err := r.RegisterCargo("G3", 10, "X", true); err != nil {
		t.Fatal(err)
	}
	if _, err := r.Adjust("A1", []Op{
		{Kind: OpLoad, CargoID: "G1", Target: "C1"},
		{Kind: OpLoad, CargoID: "G2", Target: "C2"},
		{Kind: OpLoad, CargoID: "G3", Target: "C1"},
	}); err != nil {
		t.Fatal(err)
	}
	// 卸下 G3 合法；移动 G1 到 C2 会导致 C2 超重（50+60 > 100），整次失败。
	se := requireError(t, func() error {
		_, err := r.Adjust("A2", []Op{
			{Kind: OpUnload, CargoID: "G3"},        // 合法
			{Kind: OpMove, CargoID: "G1", Target: "C2"}, // 超重
		})
		return err
	}(), ErrOverweight)
	if se.ID != "C2" {
		t.Fatalf("超重应指出舱位，实际 ID=%q", se.ID)
	}
	// 三件货物归属都不变。
	cv1, _ := r.Cargo("G1")
	cv2, _ := r.Cargo("G2")
	cv3, _ := r.Cargo("G3")
	if cv1.CompartmentID != "C1" || cv2.CompartmentID != "C2" || cv3.CompartmentID != "C1" {
		t.Fatalf("失败调整不应改变任何货物归属: %+v %+v %+v", cv1, cv2, cv3)
	}
	cpt1, _ := r.Compartment("C1")
	cpt2, _ := r.Compartment("C2")
	if cpt1.UsedWeight != 70 || cpt2.UsedWeight != 50 {
		t.Fatalf("失败调整不应改变舱位重量: %+v %+v", cpt1, cpt2)
	}
}

// ---------- 调整编号幂等 ----------

func TestAdjustmentIDIdempotent(t *testing.T) {
	r := NewRegistry()
	if err := r.RegisterCompartment("C1", 100); err != nil {
		t.Fatal(err)
	}
	if err := r.RegisterCompartment("C2", 100); err != nil {
		t.Fatal(err)
	}
	if err := r.RegisterCargo("G1", 10, "X", true); err != nil {
		t.Fatal(err)
	}
	if err := r.RegisterCargo("G2", 20, "X", true); err != nil {
		t.Fatal(err)
	}
	// 首次成功。
	res1, err := r.Adjust("A1", []Op{{Kind: OpLoad, CargoID: "G1", Target: "C1"}})
	if err != nil {
		t.Fatal(err)
	}
	// 之后另有调整。
	if _, err := r.Adjust("A2", []Op{{Kind: OpLoad, CargoID: "G2", Target: "C2"}}); err != nil {
		t.Fatal(err)
	}
	// 以相同编号、相同内容（顺序不同）重复提交。
	res2, err := r.Adjust("A1", []Op{{Kind: OpLoad, CargoID: "G1", Target: "C1"}})
	if err != nil {
		t.Fatal(err)
	}
	if res2.ID != res1.ID {
		t.Fatalf("重复提交应返回首次结果: %+v", res2)
	}
	if len(res2.CargoChanges) != len(res1.CargoChanges) {
		t.Fatalf("重复提交应返回首次结果的货物变化")
	}
	if res2.CargoChanges[0].From != "" || res2.CargoChanges[0].To != "C1" {
		t.Fatalf("重复提交应返回首次结果: %+v", res2.CargoChanges[0])
	}
	// 配载未被重复提交改变：G1 仍在 C1，G2 仍在 C2。
	cv1, _ := r.Cargo("G1")
	cv2, _ := r.Cargo("G2")
	if cv1.CompartmentID != "C1" || cv2.CompartmentID != "C2" {
		t.Fatalf("重复提交不应改变配载: %+v %+v", cv1, cv2)
	}
}

// 卸下操作忽略目标值：重复提交时卸下目标的变化不影响重复识别，
// 返回首次成功结果且不再次改变配载。
func TestAdjustmentIdempotentIgnoresUnloadTarget(t *testing.T) {
	r := NewRegistry()
	if err := r.RegisterCompartment("C1", 100); err != nil {
		t.Fatal(err)
	}
	if err := r.RegisterCompartment("C2", 100); err != nil {
		t.Fatal(err)
	}
	if err := r.RegisterCargo("G1", 30, "X", true); err != nil {
		t.Fatal(err)
	}
	if _, err := r.Adjust("A0", []Op{{Kind: OpLoad, CargoID: "G1", Target: "C1"}}); err != nil {
		t.Fatal(err)
	}
	// 第一次卸下：目标留空。
	res1, err := r.Adjust("A1", []Op{{Kind: OpUnload, CargoID: "G1"}})
	if err != nil {
		t.Fatal(err)
	}
	if res1.CargoChanges[0].From != "C1" || res1.CargoChanges[0].To != "" {
		t.Fatalf("卸下变化错误: %+v", res1.CargoChanges[0])
	}
	if res1.CompartmentChanges[0].CompartmentID != "C1" ||
		res1.CompartmentChanges[0].WeightBefore != 30 ||
		res1.CompartmentChanges[0].WeightAfter != 0 {
		t.Fatalf("舱位重量变化错误: %+v", res1.CompartmentChanges[0])
	}
	// 第二次仍以 A1 卸下 G1，但填写了目标（已登记舱位、不存在的舱位、
	// 仅空白均应同样忽略）：返回首次结果，不报冲突，不再次扣除重量。
	for _, target := range []string{"C2", "CX", "   "} {
		res2, err := r.Adjust("A1", []Op{{Kind: OpUnload, CargoID: "G1", Target: target}})
		if err != nil {
			t.Fatalf("卸下目标 %q 不应影响重复识别: %v", target, err)
		}
		if res2.CargoChanges[0].From != "C1" || res2.CargoChanges[0].To != "" {
			t.Fatalf("应返回首次结果: %+v", res2.CargoChanges[0])
		}
		if res2.CompartmentChanges[0].WeightBefore != 30 || res2.CompartmentChanges[0].WeightAfter != 0 {
			t.Fatalf("应返回首次重量变化: %+v", res2.CompartmentChanges[0])
		}
	}
	cv, _ := r.Compartment("C1")
	if cv.UsedWeight != 0 {
		t.Fatalf("重复提交不应再次扣除重量: %+v", cv)
	}
	// G1 经另一调整装入 C2 后，再提交旧调整仍返回原结果，不再次卸下。
	if _, err := r.Adjust("A2", []Op{{Kind: OpLoad, CargoID: "G1", Target: "C2"}}); err != nil {
		t.Fatal(err)
	}
	res3, err := r.Adjust("A1", []Op{{Kind: OpUnload, CargoID: "G1", Target: "C1"}})
	if err != nil {
		t.Fatalf("旧调整重复提交不应报错: %v", err)
	}
	if res3.CargoChanges[0].From != "C1" || res3.CargoChanges[0].To != "" {
		t.Fatalf("应按原结果返回，不得按当前配载重算: %+v", res3.CargoChanges[0])
	}
	cv1, _ := r.Cargo("G1")
	if cv1.CompartmentID != "C2" {
		t.Fatalf("重复提交旧调整不得再次卸下当前货物: %+v", cv1)
	}
}

// 首次填了卸下目标、再次删掉或更换目标，同样识别为原调整。
